import { postApi } from "./api/client";

export const KNOWN_TOPICS = ["product", "engineering", "design"] as const;
export type Topic = (typeof KNOWN_TOPICS)[number];

type ValidationError = { kind: "email_error"; message: string } | { kind: "topic_error"; message: string };

function validateEmailAndTopic(email: string, topic: string): ValidationError | null {
  if (!/^\S+@\S+$/.test(email)) {
    return { kind: "email_error", message: `"${email}" is not a valid email address` };
  }
  if (!KNOWN_TOPICS.includes(topic as Topic)) {
    return { kind: "topic_error", message: `"${topic}" is not a known topic` };
  }
  return null;
}

function asRecord(body: unknown): Record<string, unknown> | null {
  return typeof body === "object" && body !== null ? (body as Record<string, unknown>) : null;
}

export type SubscribeResult =
  | { kind: "subscribed"; subscriberId: string }
  | ValidationError
  | { kind: "connection_error"; message: string }
  | { kind: "response_error"; message: string };

export async function subscribe(email: string, topic: string): Promise<SubscribeResult> {
  const validationError = validateEmailAndTopic(email, topic);
  if (validationError) {
    return validationError;
  }

  let body: unknown;
  try {
    body = await postApi("newsletter.subscribe", { email, topic });
  } catch {
    return { kind: "connection_error", message: "could not reach the newsletter service" };
  }

  const record = asRecord(body);
  if (record === null || typeof record.subscriberId !== "string") {
    return { kind: "response_error", message: "unexpected response from the newsletter service" };
  }
  return { kind: "subscribed", subscriberId: record.subscriberId };
}

export type UnsubscribeResult =
  | { kind: "unsubscribed" }
  | ValidationError
  | { kind: "connection_error"; message: string }
  | { kind: "not_subscribed_error"; message: string }
  | { kind: "response_error"; message: string };

export async function unsubscribe(email: string, topic: string): Promise<UnsubscribeResult> {
  const validationError = validateEmailAndTopic(email, topic);
  if (validationError) {
    return validationError;
  }

  let body: unknown;
  try {
    body = await postApi("newsletter.unsubscribe", { email, topic });
  } catch {
    return { kind: "connection_error", message: "could not reach the newsletter service" };
  }

  const record = asRecord(body);
  if (record?.error === "not_subscribed") {
    return { kind: "not_subscribed_error", message: `"${email}" is not subscribed to "${topic}"` };
  }
  if (record?.removed === true) {
    return { kind: "unsubscribed" };
  }
  return { kind: "response_error", message: "unexpected response from the newsletter service" };
}

